-- REVIEW ONLY. One CREATE OR REPLACE statement. Execute as SQL script in DBeaver.
USE auxiliares;
DELIMITER $$
CREATE OR REPLACE TRIGGER `TRG_FB_CONSULTA_CONTACTO_ALTA` AFTER INSERT ON `FB_CIU_CONSULTAS_WEB` FOR EACH ROW
BEGIN
DECLARE v_version INT DEFAULT 0; DECLARE v_origen BIGINT DEFAULT 0;
IF NEW.ACTUALIZA_CONTACTO=1 THEN
 IF EXISTS (SELECT 1 FROM FB_CIU_CONSULTAS_WEB WHERE ID_PERSONA=NEW.ID_PERSONA AND ID_CONSULTA>NEW.ID_CONSULTA) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_CONSULTA_HISTORICA'; END IF;
 SELECT COALESCE(MAX(VERSION),0),COALESCE(MAX(ID_CONSULTA),0) INTO v_version,v_origen FROM FB_CONTACTOS WHERE ID_PERSONA=NEW.ID_PERSONA;
 IF v_version<>NEW.CONTACTO_VERSION_ESPERADA THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_CONTACTO_VERSION'; END IF;
 IF v_origen>NEW.ID_CONSULTA THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_ORIGEN_ANTIGUO'; END IF;
 IF v_version=0 THEN
  INSERT INTO FB_CONTACTOS (`ID_CONSULTA`,`TELEFONO_1`,`TIPO_TELEFONO_1`,`TELEFONO_2`,`TIPO_TELEFONO_2`,`TELEFONO_3`,`TIPO_TELEFONO_3`,`TELEFONO_4`,`TIPO_TELEFONO_4`,`TELEFONO_5`,`TIPO_TELEFONO_5`,`MAIL_1`,`MAIL_2`,`MAIL_3`,`MAIL_4`,`MAIL_5`,`NOMBRE_COMPLETO`,`TIPO_DOCUMENTO`,`DOCUMENTO`,`USUARIO_MODIFICADOR_ID`,`ID_PERSONA`) VALUES (NEW.`ID_CONSULTA`,NEW.`TELEFONO_1`,NEW.`TIPO_TELEFONO_1`,NEW.`TELEFONO_2`,NEW.`TIPO_TELEFONO_2`,NEW.`TELEFONO_3`,NEW.`TIPO_TELEFONO_3`,NEW.`TELEFONO_4`,NEW.`TIPO_TELEFONO_4`,NEW.`TELEFONO_5`,NEW.`TIPO_TELEFONO_5`,NEW.`MAIL_1`,NEW.`MAIL_2`,NEW.`MAIL_3`,NEW.`MAIL_4`,NEW.`MAIL_5`,NEW.`NOMBRE_COMPLETO`,NEW.`TIPO_DOCUMENTO`,NEW.`DOCUMENTO`,NEW.USUARIO_CREADOR_ID,NEW.`ID_PERSONA`);
 ELSE
  UPDATE FB_CONTACTOS SET `ID_CONSULTA`=NEW.`ID_CONSULTA`,`TELEFONO_1`=NEW.`TELEFONO_1`,`TIPO_TELEFONO_1`=NEW.`TIPO_TELEFONO_1`,`TELEFONO_2`=NEW.`TELEFONO_2`,`TIPO_TELEFONO_2`=NEW.`TIPO_TELEFONO_2`,`TELEFONO_3`=NEW.`TELEFONO_3`,`TIPO_TELEFONO_3`=NEW.`TIPO_TELEFONO_3`,`TELEFONO_4`=NEW.`TELEFONO_4`,`TIPO_TELEFONO_4`=NEW.`TIPO_TELEFONO_4`,`TELEFONO_5`=NEW.`TELEFONO_5`,`TIPO_TELEFONO_5`=NEW.`TIPO_TELEFONO_5`,`MAIL_1`=NEW.`MAIL_1`,`MAIL_2`=NEW.`MAIL_2`,`MAIL_3`=NEW.`MAIL_3`,`MAIL_4`=NEW.`MAIL_4`,`MAIL_5`=NEW.`MAIL_5`,`NOMBRE_COMPLETO`=NEW.`NOMBRE_COMPLETO`,`TIPO_DOCUMENTO`=NEW.`TIPO_DOCUMENTO`,`DOCUMENTO`=NEW.`DOCUMENTO`,`USUARIO_MODIFICADOR_ID`=NEW.USUARIO_CREADOR_ID
  WHERE ID_PERSONA=NEW.ID_PERSONA AND VERSION=v_version;
 END IF;
END IF;
END$$
DELIMITER ;
